#pragma once

#include <QString>
#include <cstdint>

// Values captured from the config form and forwarded to the worker session.
struct BridgeConfig {
    QString server;   // full URL including scheme; https:// is assumed if omitted
    QString user;
    QString pass;
    QString udp;      // "host:port" — empty host means 0.0.0.0
    bool    forceDup = false;
};

// A decoded WSJT-X bridge token — the copy-pasteable blob generated by the
// Noctalum web UI that packs server URL, helper token, contest ID and
// (optionally) the contest's expected station callsign into one string.
// The token flow lets the GUI skip login + contest selection entirely:
// the helper token authenticates the operator on every QSO submission,
// the contest ID names the target contest, and the station callsign lets
// the bridge silently ignore QSOs that WSJT-X logged under a different
// call.
struct BridgeToken {
    QString serverBase;   // "https://host[:port]" without trailing slash
    QString helperToken;  // per-user helper token from the server
    qint64  contestID = 0;
    QString stationCall;  // may be empty for tokens minted before v0.76
};

// One contest as returned by GET /api/contests.
struct Contest {
    int64_t id = 0;
    QString name;
    QString stationCall;
    QString status;
};

// One completed QSO parsed from a WSJT-X LOG_QSO packet.  Only the fields
// the server actually uses; the rest of the WSJT-X payload is discarded.
struct LogQSO {
    qint64  timeSec = 0;       // Unix seconds, UTC
    QString call;
    QString grid;
    quint64 freqHz = 0;
    QString mode;
    QString rstSent;
    QString rstReceived;
    QString notes;
    // Station callsign the WSJT-X sender was configured with when this
    // QSO was logged.  Compared client-side against the contest's
    // expected station_call (when the token carries one), and also
    // forwarded to the server as `my_call` so the safety-net check on
    // /api/wsjtx/qsos can catch mismatches even if the client filter is
    // bypassed.
    QString myCall;
};
